const initSqlJs = require('./vendor/sql-wasm.cjs');
const { writeFileSync, readFileSync } = require('node:fs');
initSqlJs({ locateFile: file => __dirname + '/vendor/' + file }).then(SQL => {
  const db = new SQL.Database();
  let bytes;
  try {
    db.run(`CREATE TABLE notes(id INTEGER PRIMARY KEY, text TEXT);
INSERT INTO notes VALUES (1,'First');`);
    bytes = db.export();
    db.run(`INSERT INTO notes VALUES (2,'Later');`);
    console.log(db.exec('SELECT COUNT(*) FROM notes')[0].values[0][0]);
  } finally {
    db.close();
  }
  writeFileSync('study.sqlite', bytes, { flag: 'wx' });
  const saved = readFileSync('study.sqlite');
  const reopened = new SQL.Database(saved);
  try {
    console.log(JSON.stringify(reopened.exec('SELECT id,text FROM notes ORDER BY id')[0].values));
  } finally {
    reopened.close();
  }
}).catch(error => { console.error(error.message); process.exitCode = 1; });

